import AppKit
import SwiftUI

final class RecordingHUD {
  private var panel: HUDPanel?
  private var hideTask: Task<Void, Never>?

  func showRecordingStarted(appName: String, bundleID: String?) {
    show(
      content: HUDContentView(
        title: "Recording Started",
        subtitle: appName,
        icon: NSApplication.shared.applicationIconImage
      ))
  }

  func showRecordingSaved(appName: String) {
    show(
      content: HUDContentView(
        title: "Recording Saved",
        subtitle: appName,
        icon: NSApplication.shared.applicationIconImage
      ),
      duration: 10,
      onClick: {
        NSApplication.shared.activate(ignoringOtherApps: true)
        for window in NSApplication.shared.windows
        where !(window is NSPanel) && window.canBecomeMain {
          window.makeKeyAndOrderFront(nil)
          return
        }
      }
    )
  }

  func showError(message: String) {
    show(
      content: HUDContentView(
        title: "Error",
        subtitle: message,
        icon: NSApplication.shared.applicationIconImage
      ),
      duration: 5
    )
  }

  private func show(
    content: HUDContentView, duration: Double = 2.5, onClick: (() -> Void)? = nil
  ) {
    hideTask?.cancel()
    panel?.close()

    let hosting = NSHostingView(rootView: content)
    let size = hosting.fittingSize
    hosting.frame = NSRect(origin: .zero, size: size)

    let panel = HUDPanel(
      contentRect: NSRect(origin: .zero, size: size),
      styleMask: [.borderless, .nonactivatingPanel],
      backing: .buffered, defer: false
    )
    panel.isOpaque = false
    panel.backgroundColor = .clear
    panel.level = .floating
    panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .transient]
    panel.hasShadow = true
    panel.hidesOnDeactivate = false
    panel.contentView = hosting
    panel.onClick = onClick

    if let screen = NSScreen.main {
      let x = screen.visibleFrame.maxX - size.width - 16
      let y = screen.visibleFrame.maxY - size.height - 16
      panel.setFrameOrigin(NSPoint(x: x, y: y))
    }

    panel.alphaValue = 0
    panel.orderFrontRegardless()
    NSAnimationContext.runAnimationGroup { ctx in
      ctx.duration = 0.25
      panel.animator().alphaValue = 1
    }

    self.panel = panel

    NSAccessibility.post(
      element: panel as Any, notification: .announcementRequested,
      userInfo: [.announcement: content.title])

    hideTask = Task {
      try? await Task.sleep(for: .seconds(duration))
      guard !Task.isCancelled else { return }
      self.dismiss()
    }
  }

  private func dismiss() {
    guard let panel else { return }
    self.panel = nil
    NSAnimationContext.runAnimationGroup { ctx in
      ctx.duration = 0.25
      panel.animator().alphaValue = 0
    } completionHandler: {
      Task { @MainActor in
        panel.close()
      }
    }
  }
}

