import AVFoundation
import SwiftUI
import UniformTypeIdentifiers

enum MainTab: Hashable {
  case recordings
  case settings
}

struct MainWindowView: View {
  @Binding var selectedTab: MainTab

  var body: some View {
    TabView(selection: $selectedTab) {
      RecordingsView()
        .tabItem { Label("Recordings", systemImage: "waveform") }
        .tag(MainTab.recordings)
      SettingsView()
        .tabItem { Label("Settings", systemImage: "gearshape") }
        .tag(MainTab.settings)
    }
    .frame(minWidth: 700, minHeight: 450)
  }
}

// MARK: - Recordings

struct RecordingsView: View {
  @AppStorage("saveDirectoryPath") private var saveDirectoryPath = defaultSaveDirectoryPath
  @State private var recordings: [RecordingFile] = []
  @State private var selectedRecordingID: String?
  @State private var exportError: String?
  @State private var reloadTask: Task<Void, Never>?

  var body: some View {
    NavigationSplitView {
      recordingsList
    } detail: {
      if let id = selectedRecordingID,
        let recording = recordings.first(where: { $0.id == id })
      {
        RecordingDetailView(
          recording: recording,
          onDelete: { deleteRecordings(Set([id])) },
          onTranscriptChanged: { Task { await loadRecordings() } },
          onTitleChanged: { Task { await loadRecordings() } }
        )
        .id(id)
      } else {
        ContentUnavailableView(
          "Select a Recording",
          systemImage: "waveform",
          description: Text("Choose a recording to play or transcribe.")
        )
      }
    }
    .task { await loadRecordings() }
    .onReceive(
      NotificationCenter.default.publisher(for: NSApplication.didBecomeActiveNotification)
    ) { _ in
      reloadTask?.cancel()
      reloadTask = Task {
        try? await Task.sleep(for: .milliseconds(500))
        guard !Task.isCancelled else { return }
        await loadRecordings()
      }
    }
    .alert(
      "Export Failed",
      isPresented: Binding(
        get: { exportError != nil },
        set: { if !$0 { exportError = nil } }
      )
    ) {
      Button("OK") { exportError = nil }
    } message: {
      Text(exportError ?? "")
    }
  }

  // MARK: - Sidebar List

  private var recordingsList: some View {
    Group {
      if recordings.isEmpty {
        ContentUnavailableView(
          "No Recordings",
          systemImage: "waveform",
          description: Text("Recordings will appear here when myproject-d captures audio.")
        )
      } else {
        List(recordings, selection: $selectedRecordingID) { recording in
          RecordingRow(
            recording: recording,
            onRename: { newTitle in
              renameRecording(recording, to: newTitle)
            }
          )
          .contextMenu {
            Button("Reveal in Finder") { revealInFinder(Set([recording.id])) }
            Button("Export Audio...") { exportRecordings(Set([recording.id])) }
            Divider()
            Button("Delete", role: .destructive) {
              deleteRecordings(Set([recording.id]))
            }
          }
        }
      }
    }
    .frame(minWidth: 220)
    .navigationSplitViewColumnWidth(min: 220, ideal: 260)
    .toolbar {
      ToolbarItem(placement: .automatic) {
        Text("\(recordings.count) recordings, \(totalSizeFormatted)")
          .font(.caption)
          .foregroundStyle(.secondary)
      }
    }
  }

  // MARK: - Data

  private var totalSizeFormatted: String {
    let total = recordings.reduce(0) { $0 + $1.size }
    return ByteCountFormatter.string(fromByteCount: Int64(total), countStyle: .file)
  }

  // Directory enumeration + resourceValues is synchronous I/O that blocks MainActor.
  // With hundreds of recordings this freezes the UI on every window activation.
  private func loadRecordings() async {
    let dir = URL(fileURLWithPath: saveDirectoryPath)
    let loaded: [RecordingFile] = await Task.detached {
      guard
        let files = try? FileManager.default.contentsOfDirectory(
          at: dir,
          includingPropertiesForKeys: [.contentModificationDateKey, .fileSizeKey],
          options: .skipsHiddenFiles)
      else { return [] }

      var results: [RecordingFile] = []

      for url in files where url.pathExtension == "myproject-d" {
        let audioURL = url.appendingPathComponent("audio.m4a")
        guard FileManager.default.fileExists(atPath: audioURL.path) else { continue }
        let metadata = RecordingMetadata.load(in: url)
        let audioValues = try? audioURL.resourceValues(forKeys: [.fileSizeKey])
        let sidecar = TranscriptDocument.sidecarURL(for: url)
        results.append(
          RecordingFile(
            url: url,
            audioURL: audioURL,
            title: metadata?.title ?? url.deletingPathExtension().lastPathComponent,
            date: metadata?.createdAt
              ?? (try? url.resourceValues(
                forKeys: [.contentModificationDateKey]
              ).contentModificationDate) ?? .distantPast,
            size: audioValues?.fileSize ?? 0,
            hasTranscript: FileManager.default.fileExists(atPath: sidecar.path)
          ))
      }

      return results.sorted { $0.date > $1.date }
    }.value
    recordings = loaded
  }

  // MARK: - Actions

  private func revealInFinder(_ ids: Set<String>) {
    let urls = recordings.filter { ids.contains($0.id) }.map(\.url)
    guard !urls.isEmpty else { return }
    NSWorkspace.shared.activateFileViewerSelecting(urls)
  }

  private func exportRecordings(_ ids: Set<String>) {
    let sources = recordings.filter { ids.contains($0.id) }.map(\.audioURL)
    guard !sources.isEmpty else { return }

    if sources.count == 1, let source = sources.first {
      let panel = NSSavePanel()
      panel.nameFieldStringValue = source.lastPathComponent
      panel.allowedContentTypes = [.mpeg4Audio]
      guard panel.runModal() == .OK, let dest = panel.url else { return }
      do {
        try FileManager.default.copyItem(at: source, to: dest)
      } catch {
        exportError = error.localizedDescription
      }
    } else {
      let panel = NSOpenPanel()
      panel.canChooseFiles = false
      panel.canChooseDirectories = true
      panel.canCreateDirectories = true
      panel.prompt = "Export"
      panel.message = "Choose a folder to export \(sources.count) recordings"
      guard panel.runModal() == .OK, let dest = panel.url else { return }
      var failed = 0
      for source in sources {
        let target = dest.appendingPathComponent(source.lastPathComponent)
        do {
          try FileManager.default.copyItem(at: source, to: target)
        } catch {
          failed += 1
        }
      }
      if failed > 0 {
        exportError = "Failed to export \(failed) of \(sources.count) recordings"
      }
    }
  }

  private func deleteRecordings(_ ids: Set<String>) {
    for recording in recordings where ids.contains(recording.id) {
      try? FileManager.default.trashItem(at: recording.url, resultingItemURL: nil)
    }
    if let selectedRecordingID, ids.contains(selectedRecordingID) {
      self.selectedRecordingID = nil
    }
    Task { await loadRecordings() }
  }

  private func renameRecording(_ recording: RecordingFile, to newTitle: String) {
    var metadata =
      RecordingMetadata.load(in: recording.url)
      ?? RecordingMetadata(
        title: recording.title,
        createdAt: recording.date,
        appName: recording.title,
        speakers: [:]
      )
    metadata.title = newTitle
    try? metadata.save(in: recording.url)
    Task { await loadRecordings() }
  }
}

// MARK: - Recording Row

private struct RecordingRow: View {
  let recording: RecordingFile
  var onRename: (String) -> Void

  @State private var isEditing = false
  @State private var editedTitle = ""

  var body: some View {
    VStack(alignment: .leading, spacing: 4) {
      HStack {
        if isEditing {
          TextField(
            "Title", text: $editedTitle,
            onCommit: {
              let trimmed = editedTitle.trimmingCharacters(in: .whitespaces)
              if !trimmed.isEmpty {
                onRename(trimmed)
              }
              isEditing = false
            }
          )
          .textFieldStyle(.plain)
          .lineLimit(1)
          .onExitCommand { isEditing = false }
        } else {
          Text(recording.title)
            .lineLimit(1)
            .truncationMode(.middle)
            .onTapGesture(count: 2) {
              editedTitle = recording.title
              isEditing = true
            }
        }
        if recording.hasTranscript {
          Image(systemName: "text.quote")
            .font(.caption2)
            .foregroundStyle(.secondary)
        }
      }
      HStack {
        Text(recording.date, format: .dateTime.month().day().hour().minute())
        Spacer()
        Text(recording.sizeFormatted)
      }
      .font(.caption)
      .foregroundStyle(.secondary)
    }
    .padding(.vertical, 2)
  }
}

// MARK: - Recording Detail View

struct RecordingDetailView: View {
  let recording: RecordingFile
  var onDelete: () -> Void
  var onTranscriptChanged: () -> Void
  var onTitleChanged: () -> Void

  @State private var sonioxAPIKey = KeychainHelper.string(forKey: "sonioxAPIKey") ?? ""

  // Playback
  @State private var player: AVPlayer?
  @State private var isPlaying = false
  @State private var duration: TimeInterval = 0
  @State private var currentTime: TimeInterval = 0
  @State private var timeObserver: Any?
  @State private var isDragging = false
  @State private var playerError: String?

  // UI
  @State private var showDeleteConfirmation = false

  // Metadata
  @State private var metadata: RecordingMetadata?
  @State private var isEditingTitle = false
  @State private var editedTitle = ""

  // Transcription
  @State private var transcript: TranscriptDocument?
  @State private var transcriptionStatus: TranscriptionStatus = .idle
  @State private var transcriptionTask: Task<Void, Never>?

  var body: some View {
    VStack(spacing: 0) {
      metadataHeader
      Divider()
      if let playerError {
        VStack(spacing: 8) {
          Image(systemName: "exclamationmark.triangle")
            .font(.title)
            .foregroundStyle(.secondary)
          Text("Could not load audio: \(playerError)")
            .font(.caption)
            .foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
      } else {
        playbackControls
        Divider()
        transcriptArea
      }
    }
    .onAppear {
      sonioxAPIKey = KeychainHelper.string(forKey: "sonioxAPIKey") ?? ""
      loadMetadata()
      setupPlayer()
      loadTranscript()
    }
    .onDisappear {
      teardownPlayer()
      cancelTranscription()
    }
  }

  // MARK: - Header

  private var metadataHeader: some View {
    HStack {
      VStack(alignment: .leading, spacing: 4) {
        if isEditingTitle {
          TextField(
            "Title", text: $editedTitle,
            onCommit: {
              let trimmed = editedTitle.trimmingCharacters(in: .whitespaces)
              if !trimmed.isEmpty {
                saveTitle(trimmed)
              }
              isEditingTitle = false
            }
          )
          .font(.headline)
          .textFieldStyle(.plain)
          .onExitCommand { isEditingTitle = false }
        } else {
          Text(recording.title)
            .font(.headline)
            .onTapGesture(count: 2) {
              editedTitle = recording.title
              isEditingTitle = true
            }
        }
        HStack(spacing: 8) {
          Text(recording.date.formatted(.dateTime.year().month().day().hour().minute()))
          Text(recording.sizeFormatted)
          if duration > 0 {
            Text(formatTime(duration))
          }
        }
        .font(.caption)
        .foregroundStyle(.secondary)
      }
      Spacer()
      HStack(spacing: 8) {
        if transcript != nil {
          Button {
            exportTranscript()
          } label: {
            Image(systemName: "doc.text")
          }
          .help("Export Transcript")
        }

        Button {
          NSWorkspace.shared.activateFileViewerSelecting([recording.url])
        } label: {
          Image(systemName: "folder")
        }
        .help("Reveal in Finder")

        Button(role: .destructive) {
          showDeleteConfirmation = true
        } label: {
          Image(systemName: "trash")
        }
        .help("Delete")
      }
    }
    .padding()
    .alert("Delete Recording?", isPresented: $showDeleteConfirmation) {
      Button("Delete", role: .destructive, action: onDelete)
      Button("Cancel", role: .cancel) {}
    } message: {
      Text("This will move \"\(recording.title)\" to the Trash.")
    }
  }

  // MARK: - Playback

  private var playbackControls: some View {
    VStack(spacing: 8) {
      Slider(
        value: $currentTime,
        in: 0...max(duration, 0.01)
      ) { editing in
        isDragging = editing
        if !editing {
          seekTo(currentTime)
        }
      }

      HStack {
        Text(formatTime(currentTime))
          .font(.caption.monospacedDigit())
          .foregroundStyle(.secondary)
        Spacer()
        Text("-\(formatTime(max(0, duration - currentTime)))")
          .font(.caption.monospacedDigit())
          .foregroundStyle(.secondary)
      }

      HStack(spacing: 20) {
        Button {
          skip(by: -15)
        } label: {
          Image(systemName: "gobackward.15")
            .font(.title3)
        }
        .buttonStyle(.plain)

        Button {
          togglePlayback()
        } label: {
          Image(systemName: isPlaying ? "pause.circle.fill" : "play.circle.fill")
            .font(.largeTitle)
        }
        .buttonStyle(.plain)

        Button {
          skip(by: 15)
        } label: {
          Image(systemName: "goforward.15")
            .font(.title3)
        }
        .buttonStyle(.plain)
      }
    }
    .padding()
  }

  private func setupPlayer() {
    let asset = AVURLAsset(url: recording.audioURL)
    let item = AVPlayerItem(asset: asset)
    let p = AVPlayer(playerItem: item)
    player = p
    playerError = nil
    currentTime = 0

    // Get duration once asset is loaded
    Task {
      do {
        let dur = try await asset.load(.duration)
        duration = dur.seconds.isFinite ? dur.seconds : 0
      } catch {
        playerError = error.localizedDescription
        Log.error(
          Log.app, "playback",
          "failed to load asset: \(error.localizedDescription)")
      }
    }

    // Periodic time observer (10x/sec)
    let interval = CMTime(seconds: 0.1, preferredTimescale: 600)
    timeObserver = p.addPeriodicTimeObserver(forInterval: interval, queue: .main) { time in
      Task { @MainActor in
        if !isDragging {
          currentTime = time.seconds
        }
      }
    }

    // End-of-track notification
    endObserver = NotificationCenter.default.addObserver(
      forName: .AVPlayerItemDidPlayToEndTime,
      object: item,
      queue: .main
    ) { _ in
      Task { @MainActor in
        isPlaying = false
        currentTime = 0
        p.seek(to: .zero)
      }
    }
  }

  @State private var endObserver: (any NSObjectProtocol)?

  private func teardownPlayer() {
    if let observer = timeObserver {
      player?.removeTimeObserver(observer)
      timeObserver = nil
    }
    if let observer = endObserver {
      NotificationCenter.default.removeObserver(observer)
      endObserver = nil
    }
    player?.pause()
    player = nil
    isPlaying = false
    currentTime = 0
  }

  private func togglePlayback() {
    guard let player else { return }
    if isPlaying {
      player.pause()
    } else {
      player.play()
    }
    isPlaying = !isPlaying
  }

  private func seekTo(_ time: TimeInterval) {
    let cmTime = CMTime(seconds: time, preferredTimescale: 600)
    player?.seek(to: cmTime, toleranceBefore: .zero, toleranceAfter: .zero)
    currentTime = time
  }

  private func skip(by seconds: TimeInterval) {
    let newTime = max(0, min(duration, currentTime + seconds))
    seekTo(newTime)
  }

  // MARK: - Metadata

  private func loadMetadata() {
    metadata = RecordingMetadata.load(in: recording.url)
  }

  private func saveTitle(_ newTitle: String) {
    var meta =
      metadata
      ?? RecordingMetadata(
        title: recording.title,
        createdAt: recording.date,
        appName: recording.title,
        speakers: [:]
      )
    meta.title = newTitle
    try? meta.save(in: recording.url)
    metadata = meta
    onTitleChanged()
  }

  private func speakerName(for speakerID: Int) -> String {
    if let name = metadata?.speakers[String(speakerID)], !name.isEmpty {
      return name
    }
    return speakerID == -1 ? "You" : "Speaker \(speakerID + 1)"
  }

  private func saveSpeakerName(_ name: String, for speakerID: Int) {
    var meta =
      metadata
      ?? RecordingMetadata(
        title: recording.title,
        createdAt: recording.date,
        appName: recording.title,
        speakers: [:]
      )
    meta.speakers[String(speakerID)] = name
    try? meta.save(in: recording.url)
    metadata = meta
  }

  // MARK: - Transcript

  private var transcriptArea: some View {
    Group {
      if let transcript, !transcript.segments.isEmpty {
        transcriptView(transcript)
      } else if case .error(let msg) = transcriptionStatus {
        VStack(spacing: 12) {
          Image(systemName: "exclamationmark.triangle")
            .font(.title)
            .foregroundStyle(.secondary)
          Text(msg)
            .font(.caption)
            .foregroundStyle(.secondary)
            .multilineTextAlignment(.center)
          Button("Retry") { startTranscription() }
            .buttonStyle(.bordered)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
      } else if transcriptionStatus != .idle {
        VStack(spacing: 12) {
          ProgressView()
          Text(transcriptionStatusText)
            .font(.caption)
            .foregroundStyle(.secondary)
          Button("Cancel") { cancelTranscription() }
            .buttonStyle(.bordered)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
      } else {
        VStack(spacing: 12) {
          if sonioxAPIKey.isEmpty {
            Text("Add your Soniox API key in Settings to enable transcription")
              .font(.caption)
              .foregroundStyle(.secondary)
              .multilineTextAlignment(.center)
          } else {
            Button("Transcribe") { startTranscription() }
              .buttonStyle(.borderedProminent)
          }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
      }
    }
  }

  private var transcriptionStatusText: String {
    switch transcriptionStatus {
    case .uploading: "Uploading audio..."
    case .queued: "Queued for transcription..."
    case .transcribing: "Transcribing..."
    default: ""
    }
  }

  private func transcriptView(_ doc: TranscriptDocument) -> some View {
    ScrollView {
      LazyVStack(alignment: .leading, spacing: 12) {
        ForEach(doc.segments) { segment in
          TranscriptSegmentView(
            segment: segment,
            speakerName: speakerName(for: segment.speaker),
            isActive: isSegmentActive(segment, in: doc),
            onTap: { jumpTo(time: segment.time) },
            onRenameSpeaker: { newName in
              saveSpeakerName(newName, for: segment.speaker)
            }
          )
        }
      }
      .padding()
    }
  }

  private func isSegmentActive(
    _ segment: TranscriptSegment, in doc: TranscriptDocument
  ) -> Bool {
    guard isPlaying else { return false }
    guard let idx = doc.segments.firstIndex(where: { $0.id == segment.id }) else {
      return false
    }
    let nextTime: Double =
      if idx + 1 < doc.segments.count {
        doc.segments[idx + 1].time
      } else {
        duration
      }
    return currentTime >= segment.time && currentTime < nextTime
  }

  private func jumpTo(time: Double) {
    seekTo(time)
    if !isPlaying { togglePlayback() }
  }

  // MARK: - Transcription Lifecycle

  private func loadTranscript() {
    transcript = TranscriptDocument.load(for: recording.url)
    transcriptionStatus = .idle
  }

  private func startTranscription() {
    guard !sonioxAPIKey.isEmpty else { return }

    transcriptionTask = Task {
      let service = TranscriptionService(apiKey: sonioxAPIKey)
      transcriptionStatus = .uploading

      do {
        let doc = try await service.transcribe(
          fileURL: recording.audioURL,
          onStatus: { status in
            transcriptionStatus = status
          }
        )
        // Show transcript immediately, then persist
        transcript = doc
        transcriptionStatus = .completed
        onTranscriptChanged()
        do {
          try doc.save(for: recording.url)
        } catch {
          Log.error(
            Log.transcription, "transcription",
            "failed to save transcript: \(error.localizedDescription)")
        }
      } catch is CancellationError {
        transcriptionStatus = .idle
      } catch let error as URLError where error.code == .cancelled {
        // URLSession throws URLError.cancelled when Task is cancelled
        if Task.isCancelled {
          transcriptionStatus = .idle
        } else {
          transcriptionStatus = .error(error.localizedDescription)
        }
      } catch {
        if Task.isCancelled {
          transcriptionStatus = .idle
        } else {
          transcriptionStatus = .error(error.localizedDescription)
          Log.error(
            Log.transcription, "transcription",
            "failed: \(error.localizedDescription)")
        }
      }
    }
  }

  private func cancelTranscription() {
    transcriptionTask?.cancel()
    transcriptionTask = nil
    if case .error = transcriptionStatus { return }
    transcriptionStatus = .idle
  }

  // MARK: - Transcript Export

  private func exportTranscript() {
    guard let transcript, !transcript.segments.isEmpty else { return }

    let panel = NSSavePanel()
    panel.nameFieldStringValue = "\(recording.title).json"
    panel.allowedContentTypes = [.json]
    guard panel.runModal() == .OK, let dest = panel.url else { return }

    let segments = transcript.segments.map { segment in
      let m = Int(segment.time) / 60
      let s = Int(segment.time) % 60
      return ExportedSegment(
        speaker: speakerName(for: segment.speaker),
        time: String(format: "%d:%02d", m, s),
        text: segment.text
      )
    }

    let encoder = JSONEncoder()
    encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
    do {
      let data = try encoder.encode(segments)
      try data.write(to: dest, options: .atomic)
    } catch {
      Log.error(
        Log.app, "export",
        "failed to export transcript: \(error.localizedDescription)")
    }
  }

  // MARK: - Formatting

  private func formatTime(_ time: TimeInterval) -> String {
    let total = max(0, Int(time))
    let h = total / 3600
    let m = (total % 3600) / 60
    let s = total % 60
    return h > 0
      ? String(format: "%d:%02d:%02d", h, m, s)
      : String(format: "%d:%02d", m, s)
  }
}

